{
  "op": "aggregate",
  "collection": "personer",
  "pipeline": [
    {
      "$match": {
        "selskapRolle": { "$exists": true, "$ne": null },
        "selskapOrgNr": { "$exists": true, "$ne": null }
      }
    },
    {
      "$lookup": {
        "from": "politikere",
        "let": { "personNavn": "$navn" },
        "pipeline": [
          { "$match": { "$expr": { "$eq": ["$navn", "$$personNavn"] } } }
        ],
        "as": "matchedPolitikere"
      }
    },
    { "$match": { "matchedPolitikere.0": { "$exists": true } } },
    {
      "$group": {
        "_id": "$selskapOrgNr",
        "selskapsNavnFraPerson": { "$first": "$selskapNavn" },
        "antallPolitikerroller": { "$sum": 1 }
      }
    },
    {
      "$lookup": {
        "from": "selskap",
        "localField": "_id",
        "foreignField": "orgNr",
        "as": "selskapDoc"
      }
    },
    { "$unwind": { "path": "$selskapDoc", "preserveNullAndEmptyArrays": true } },
    {
      "$project": {
        "_id": 0,
        "selskapsnavn": { "$ifNull": ["$selskapDoc.navn", "$selskapsNavnFraPerson"] },
        "organisasjonsnummer": "$_id",
        "antallPolitikerroller": 1
      }
    }
  ]
}
